package net.civeira.phylax.feature.access.userloginthrottle.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.userloginthrottle.domain.UserLoginThrottle;
import net.civeira.phylax.feature.access.userloginthrottle.domain.event.UserLoginThrottleEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserLoginThrottleEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserLoginThrottleEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserLoginThrottle entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
